export interface ConnectorConfig {
  /** Airtable base ID (e.g., appXXXXXXXXXXXXXX) */
  baseId: string;
  /** Airtable table name (e.g., "Contacts") */
  tableName: string;
  /** Airtable API key (Bearer token). Typically from env var AIRTABLE_API_KEY */
  apiKey: string;
  /** Optional fetch implementation for testing or custom environments */
  fetch?: typeof fetch;
}

export interface JotformPayload {
  /** Email address used to locate the Airtable record (required) */
  email: string;
  /** First name from the form */
  first_name?: string;
  /** Last name from the form */
  last_name?: string;
  /** Phone number from the form */
  phone?: string;
  /** Website URL from the form */
  website?: string;
  /** Any other fields are ignored */
  [key: string]: unknown;
}

export interface HandleResult {
  /** The Airtable record ID that was looked up (and possibly updated) */
  recordId: string;
  /** Whether a PATCH request was performed */
  updated: boolean;
}

/**
 * Handles a Jotform submission webhook payload.
 * Looks up an Airtable record by email, then PATCHes only the fields that are present and non-empty in the payload.
 * @param payload The Jotform webhook JSON payload.
 * @param config Connector configuration including Airtable credentials.
 * @returns The record ID and whether an update occurred.
 * @throws Error if email is missing, no record is found, or Airtable API returns an error.
 */
export async function handle(
  payload: JotformPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const { baseId, tableName, apiKey, fetch = globalThis.fetch } = config;

  // Validate required field
  if (!payload.email || typeof payload.email !== 'string') {
    throw new Error('Missing required field: email');
  }

  const email = payload.email.trim();
  if (!email) {
    throw new Error('Email field is empty');
  }

  // Build filterByFormula: {Email}='email'
  // According to Airtable formula syntax, field names with spaces need curly braces.
  // The example uses {Email} but the actual field name might be "email". We'll assume the field is named "Email" as per the example.
  // However, the example response shows field "email" (lowercase). The formula uses {Email} (capitalized).
  // We'll follow the documented example exactly: {Email}='{{email}}'
  const formula = `{Email}='${email.replace(/'/g, "\\'")}'`;
  const encodedFormula = encodeURIComponent(formula);

  const getUrl = `https://api.airtable.com/v0/${baseId}/${tableName}?filterByFormula=${encodedFormula}`;

  const headers = {
    Authorization: `Bearer ${apiKey}`,
    'Content-Type': 'application/json',
  };

  // GET request to find record
  const getResponse = await fetch(getUrl, {
    method: 'GET',
    headers,
  });

  if (!getResponse.ok) {
    throw new Error(`Airtable GET failed: ${getResponse.status} ${getResponse.statusText} for ${getUrl}`);
  }

  const getData = (await getResponse.json()) as { records: Array<{ id: string; fields: Record<string, unknown> }> };

  if (!getData.records || getData.records.length === 0) {
    throw new Error(`No Airtable record found for email: ${email}`);
  }

  // Assume email is unique, take first record
  const record = getData.records[0];
  const recordId = record.id;

  // Determine fields to update: only those present in payload and non-empty (non-null, non-undefined, non-empty string)
  const fieldsToUpdate: Record<string, string> = {};
  const fieldMapping = ['first_name', 'last_name', 'phone', 'website'] as const;

  for (const field of fieldMapping) {
    const value = payload[field];
    if (value !== undefined && value !== null && value !== '') {
      fieldsToUpdate[field] = String(value);
    }
  }

  // If no fields to update, skip PATCH
  if (Object.keys(fieldsToUpdate).length === 0) {
    return { recordId, updated: false };
  }

  const patchUrl = `https://api.airtable.com/v0/${baseId}/${tableName}/${recordId}`;
  const patchBody = JSON.stringify({ fields: fieldsToUpdate });

  const patchResponse = await fetch(patchUrl, {
    method: 'PATCH',
    headers,
    body: patchBody,
  });

  if (!patchResponse.ok) {
    throw new Error(`Airtable PATCH failed: ${patchResponse.status} ${patchResponse.statusText} for ${patchUrl}`);
  }

  // Optionally parse response, but we just need to confirm success
  await patchResponse.json();

  return { recordId, updated: true };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, JotformPayload } from './connector';
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures';

// Contract test (must be at top level with title 'contract')
describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      baseId: 'appXXXXXXXXXXXXXX',
      tableName: 'Contacts',
      apiKey: 'test-api-key',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.recordId).toBe('recXXXXXXXXXXXXXX');
    expect(result.updated).toBe(true);
  });
});

// Helper to create a valid config with a fake fetch
function createTestConfig(fetch: typeof fetch): ConnectorConfig {
  return {
    baseId: 'appTestBase',
    tableName: 'TestTable',
    apiKey: 'test-key',
    fetch,
  };
}

describe('handle', () => {
  it('successfully updates record with all fields present', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.method === 'GET' && req.url.includes('filterByFormula')) {
        return jsonResponse({
          records: [{ id: 'rec123', fields: { email: 'user@example.com' } }],
        });
      }
      if (req.method === 'PATCH' && req.url.endsWith('/rec123')) {
        // Verify the patch body contains all fields
        const body = req.json as { fields: Record<string, string> };
        expect(body.fields).toEqual({
          first_name: 'John',
          last_name: 'Doe',
          phone: '123-456-7890',
          website: 'https://example.com',
        });
        return jsonResponse({ id: 'rec123', fields: { ...body.fields, email: 'user@example.com' } });
      }
      return jsonResponse({ error: 'Not found' }, 404);
    });

    const payload: JotformPayload = {
      email: 'user@example.com',
      first_name: 'John',
      last_name: 'Doe',
      phone: '123-456-7890',
      website: 'https://example.com',
    };

    const result = await handle(payload, createTestConfig(fetch));
    expect(result.recordId).toBe('rec123');
    expect(result.updated).toBe(true);
    expect(calls.length).toBe(2);
  });

  it('skips PATCH when no updatable fields are present', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.method === 'GET' && req.url.includes('filterByFormula')) {
        return jsonResponse({
          records: [{ id: 'rec456', fields: { email: 'user@example.com' } }],
        });
      }
      return jsonResponse({ error: 'Not found' }, 404);
    });

    const payload: JotformPayload = {
      email: 'user@example.com',
      // all optional fields missing or empty
      first_name: '',
      last_name: undefined,
      phone: null as unknown as string,
      website: '   ',
    };

    const result = await handle(payload, createTestConfig(fetch));
    expect(result.recordId).toBe('rec456');
    expect(result.updated).toBe(false);
    expect(calls.length).toBe(1); // only GET
  });

  it('throws when email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { first_name: 'John' } as JotformPayload;
    await expect(handle(payload, createTestConfig(fetch))).rejects.toThrow('Missing required field: email');
  });

  it('throws when email is empty string', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: JotformPayload = { email: '   ' };
    await expect(handle(payload, createTestConfig(fetch))).rejects.toThrow('Email field is empty');
  });

  it('throws when no record found for email', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ records: [] }, 200));
    const payload: JotformPayload = { email: 'nonexistent@example.com' };
    await expect(handle(payload, createTestConfig(fetch))).rejects.toThrow('No Airtable record found for email');
  });

  it('throws on non-2xx GET response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    const payload: JotformPayload = { email: 'user@example.com' };
    await expect(handle(payload, createTestConfig(fetch))).rejects.toThrow('Airtable GET failed: 401 Unauthorized');
  });

  it('throws on non-2xx PATCH response', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.method === 'GET') {
        return jsonResponse({ records: [{ id: 'rec789', fields: {} }] });
      }
      return jsonResponse({ error: 'Internal Server Error' }, 500);
    });

    const payload: JotformPayload = {
      email: 'user@example.com',
      first_name: 'John',
    };

    await expect(handle(payload, createTestConfig(fetch))).rejects.toThrow('Airtable PATCH failed: 500 Internal Server Error');
    expect(calls.length).toBe(2);
  });

  it('uses Authorization Bearer header', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.method === 'GET') {
        expect(req.headers.get('authorization')).toBe('Bearer test-key');
        return jsonResponse({ records: [{ id: 'recAuth', fields: {} }] });
      }
      expect(req.headers.get('authorization')).toBe('Bearer test-key');
      return jsonResponse({ id: 'recAuth', fields: {} });
    });

    const payload: JotformPayload = { email: 'user@example.com', first_name: 'Test' };
    await handle(payload, createTestConfig(fetch));
    expect(calls.length).toBe(2);
  });

  it('properly encodes email in filterByFormula', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.method === 'GET') {
        // Check that the URL contains the encoded formula
        expect(req.url).toContain('filterByFormula=%7BEmail%7D%3D%27user%40example.com%27');
        return jsonResponse({ records: [{ id: 'recEnc', fields: {} }] });
      }
      return jsonResponse({ id: 'recEnc', fields: {} });
    });

    const payload: JotformPayload = { email: 'user@example.com', first_name: 'Test' };
    await handle(payload, createTestConfig(fetch));
    expect(calls[0].url).toContain('filterByFormula=%7BEmail%7D%3D%27user%40example.com%27');
  });
});

# Jotform to Airtable Connector

This connector processes Jotform submission webhooks and updates corresponding Airtable records.

## What it does

1. Receives a Jotform webhook payload (JSON).
2. Validates that an `email` field is present.
3. Queries Airtable for a record where the `Email` field matches the submitted email (using `filterByFormula`).
4. If a record is found, builds a PATCH request with only the fields that are present and non-empty in the payload (`first_name`, `last_name`, `phone`, `website`).
5. Sends the PATCH request to update the record.
6. Returns the Airtable record ID and a boolean indicating whether an update was performed.

## Configuration

The connector requires the following configuration parameters (typically sourced from environment variables):

| Parameter | Description | Example |
|-----------|-------------|---------|
| `baseId` | Airtable base ID (e.g., `appXXXXXXXXXXXXXX`) | `appAbc123` |
| `tableName` | Airtable table name (e.g., `Contacts`) | `Contacts` |
| `apiKey` | Airtable API key (Bearer token). Usually from `AIRTABLE_API_KEY` env var. | `patXXXXXXXXXXXXXX` |

**Environment variables:**
- `AIRTABLE_API_KEY` – Your Airtable personal access token.

## Usage example

```typescript
import { handle, ConnectorConfig } from './connector';

const config: ConnectorConfig = {
  baseId: process.env.AIRTABLE_BASE_ID!,
  tableName: process.env.AIRTABLE_TABLE_NAME!,
  apiKey: process.env.AIRTABLE_API_KEY!,
};

// In your webhook handler (e.g., Express, Fastify, etc.)
app.post('/jotform-webhook', async (req, res) => {
  try {
    const result = await handle(req.body, config);
    res.json({ success: true, ...result });
  } catch (err) {
    console.error(err);
    res.status(500).json({ success: false, error: err.message });
  }
});
```

## Assumptions

- The Jotform submission contains an `email` field that uniquely identifies the Airtable record.
- Airtable record ID is not directly available; lookup uses `filterByFormula` with the email field.
- Only fields explicitly sent by Jotform should be considered for PATCH; missing fields are left untouched.
- The Airtable table has columns matching the Jotform field names (`first_name`, `last_name`, `phone`, `website`, etc.).
- The Airtable field for email is named `Email` (as used in the `filterByFormula` example). If your field name differs, adjust the formula accordingly.
- If all target fields are empty or not present in the Jotform payload, the connector skips the PATCH call.
- The connector does not create new records; it only updates existing ones.

